      `<text class="ss-dim" x="${TX + 7}" y="124">Y −1.8</text><text class="ss-dim" x="1302" y="${TY - 6}">−1.8</text><text class="ss-dim" x="1596" y="${TY - 6}" text-anchor="end">X +1.8</text>`

    // ---------- plotter under the ticket ----------
    let pgrid = ''
